import json
from decimal import Decimal,ROUND_HALF_UP
p=json.load(open('web/src/data/policy-v1.json',encoding='utf8'))
# required: each coverage area * 1250 yuan = cents and round cent, sum by item/policy
cov={c['id']:c for c in p['parcelCoverages']}
def amt(area):return int((Decimal(area)*Decimal(125000)).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
bad=[]
for i in p['enrollmentItems']:
 x=sum(amt(cov[c]['insuredAreaMu']) for c in i['parcelCoverageIds'])
 if x!=i['sum_insured_cents']:bad.append((i['id'],i['sum_insured_cents'],x,x-i['sum_insured_cents']))
print('bad items',len(bad),'examples',bad[:10], 'total delta',sum(x[3] for x in bad))
badp=[]
for pol in p['policies']:
 cs=[c for c in p['parcelCoverages'] if c['policyId']==pol['id']]
 x=sum(amt(c['insuredAreaMu']) for c in cs)
 if x!=pol['summary']['sum_insured_cents']:badp.append((pol['id'],pol['summary']['sum_insured_cents'],x,x-pol['summary']['sum_insured_cents']))
print('bad policies',badp)
PY

