import json,math,collections
from shapely.geometry import shape
p=json.load(open('web/src/data/policy-v1.json',encoding='utf8')); g=json.load(open('web/public/data/parcels/330604102014.geojson',encoding='utf8'))
cent={str(f['properties']['id']):shape(f['geometry']).centroid for f in g['features']}
# Web approximation meters
by=collections.defaultdict(list)
pol={x['id']:x for x in p['policies']}
for c in p['parcelCoverages']:
 if pol[c['policyId']]['status']=='保障中':by[c['insuredPartyId']].append(c['parcelId'])
for party,ids in by.items():
 if len(ids)<2: continue
 md=0
 for a in range(len(ids)):
  for b in range(a+1,len(ids)):
   p1,p2=cent[ids[a]],cent[ids[b]]
   dx=(p1.x-p2.x)*111320*math.cos(math.radians((p1.y+p2.y)/2));dy=(p1.y-p2.y)*110540
   md=max(md,math.hypot(dx,dy))
 if md>350: print(party,len(ids),round(md,1),pol[next(c['policyId'] for c in p['parcelCoverages'] if c['insuredPartyId']==party and pol[c['policyId']]['status']=='保障中')]['insuredMode'])
PY

